/**
 * Render API — turns a project's real design into a real FLUX image.
 *
 *   POST /api/render  { mode:"generate", ... }  → text-to-image FLUX
 *   POST /api/render  { mode:"inpaint",  ... }  → FLUX-Fill over a masked region
 *   GET  /api/render?key=...                    → stream a stored render image
 *
 * Generated bytes are persisted via the same storage layer as the parsing
 * pipeline (AWS S3 when configured, local temp dir otherwise) and served back
 * through the GET handler, so the browser never depends on Replicate's
 * short-lived output URLs.
 */

import { randomUUID } from "node:crypto";
import {
  fluxConfigured,
  generateImage,
  inpaintImage,
  type RenderView,
} from "@/lib/render/flux-client";
import {
  buildIdentityBrief,
  buildInpaintPrompt,
  buildRenderPrompt,
  cameraDescription,
  refinePromptWithGemini,
} from "@/lib/render/prompt";
import {
  describeRoomLook,
  editImageWithGemini,
  geminiImageConfigured,
  makePanoramaFromViews,
  renderPhotorealFromScreenshot,
  renderViewFromAnchor,
} from "@/lib/render/gemini-image";
import { generateVideoFromImage, veoConfigured } from "@/lib/render/veo-client";
import { verifyAndRepairRender, checkViewConsistency } from "@/lib/render/verify";
import {
  completeVideoJob,
  createVideoJob,
  failVideoJob,
  getVideoJob,
  stageVideoJob,
} from "@/lib/render/video-jobs";
import { assembleSlideshow, concatVideos, extractFramesFromVideo, ffmpegAvailable } from "@/lib/render/ffmpeg";
import { getObject, putObject } from "@/lib/pipeline/storage";
import type { DesignStyle, FloorPlan, PlacedItem, PropertyType } from "@/lib/types";

// Spawns network calls + touches storage → Node runtime, never Edge.
export const runtime = "nodejs";
export const dynamic = "force-dynamic";
// FLUX takes ~a minute; the Veo video pass (mode "video") polls a long-running op
// for a few minutes, so give the handler generous room.
export const maxDuration = 300;

interface GenerateBody {
  mode: "generate";
  projectId: string;
  view: RenderView;
  style: DesignStyle;
  propertyType: PropertyType;
  plan?: FloorPlan;
  items: PlacedItem[];
  /**
   * PNG/JPEG data URI of the captured Three.js scene. When present, FLUX runs
   * image-to-image so the render preserves the real room geometry + layout.
   */
  image?: string;
  /** Fixed seed so all of a room's views render the same, consistent design. */
  seed?: number;
  /** Optional free-text design brief from the user. */
  notes?: string;
  /**
   * Text description of the room's already-rendered HERO view (returned by the
   * hero's own generate call). When set, this is a follow-up angle: it renders
   * from its OWN 3D screenshot (its own camera) but is told to match this exact
   * look, so the whole room is ONE design without copying the hero's composition.
   * Absent = this IS the hero (it gets described and the spec returned).
   */
  lookSpec?: string;
  /**
   * Render this view as the FLUX HERO (image-to-image from its 3D screenshot).
   * The room renders ONE FLUX hero corner, then anchors the other views to it.
   */
  heroFlux?: boolean;
  /**
   * Storage key of the already-rendered hero. When set, this is a follow-up view:
   * Nano Banana conditions on the hero IMAGE for identical materials / furniture /
   * theme, while this view's own 3D screenshot supplies the (different) camera.
   */
  anchorKey?: string;
  /**
   * Per-furniture reference images (label + data URI) the user attached on the
   * room page — Nano renders each named piece to match its reference.
   */
  references?: { label: string; image: string }[];
  /**
   * Whole-room reference image (data URI) the user attached on the room page —
   * Nano matches the overall style / materials / mood to it.
   */
  styleRef?: string;
  /**
   * Storage key of an already-rendered image (the room's HERO) to use as a SOFT
   * style reference: loaded server-side and passed as the styleRef so a follow-up
   * view matches the hero's design while keeping its OWN camera. This is how the
   * room's views stay consistent without the hard-anchor camera collapse. Takes
   * precedence over `styleRef` when set.
   */
  styleRefKey?: string;
  /**
   * When set, skip the FLUX image-to-image fallback if Nano Banana was available
   * but returned nothing — return a clear retry error instead. Room views use this
   * so a rate-limited Nano render surfaces a retry rather than a rough, blocky FLUX
   * image (the "blocks where there should be a photo" complaint).
   */
  noFluxFallback?: boolean;
  /**
   * When set with `anchorKey`, a FAILED anchored render returns a retry error
   * instead of falling through to an UNANCHORED render. The walkthrough sides set
   * this: all four must share the edited front photo's design, so a side that
   * couldn't be anchored must be rejected (and refilmed), never silently produced
   * with a drifting design and then filmed into the orbit.
   */
  requireAnchor?: boolean;
}

interface InpaintBody {
  mode: "inpaint";
  projectId: string;
  /** storage key of the base image to edit (from a prior render) */
  baseKey: string;
  /** PNG mask as a data URL — white = repaint, black = keep */
  mask: string;
  instruction: string;
  style: DesignStyle;
  /** optional reference image (data URI) the user uploaded to guide the edit */
  reference?: string;
  /**
   * When set, skip the FLUX-Fill fallback if Nano Banana was available but returned
   * nothing — return a clear retry error instead. The lasso edit uses this so a
   * rate-limited edit surfaces a retry rather than a FLUX-Fill result confined to
   * the strict lasso outline (which reads as "the edit didn't work").
   */
  noFluxFallback?: boolean;
}

interface PanoBody {
  mode: "pano";
  projectId: string;
  /** storage keys of the rendered views to merge into a 360° panorama */
  imageKeys: string[];
  style: DesignStyle;
  propertyType: PropertyType;
  /** Optional free-text design brief from the user. */
  notes?: string;
}

interface VideoBody {
  mode: "video";
  projectId: string;
  /** the room's front render (data URI) — the single source of truth for the clip */
  image: string;
  /** camera-motion prompt for the orbit/pan (LEGACY single-clip path) */
  prompt: string;
  /**
   * GROUNDED 360° ORBIT (the non-hallucinating path): photoreal stills of all
   * four sides, clockwise from the front. When set (with `segmentPrompts`), the
   * walkthrough is FOUR Veo clips — each interpolating first→last frame between
   * consecutive stills — concatenated into one seamless mp4. Every wall is a
   * real endpoint the clip must pass through: all 4 sides shown, equal time,
   * nothing invented. Without it, the legacy one-clip pan runs (roomless scenes).
   */
  sides?: { front: string; right: string; back: string; left: string };
  /** one Veo prompt per orbit segment, clockwise: F→R, R→B, B→L, L→F */
  segmentPrompts?: string[];
  /**
   * Gallery still records (already stored) to echo into the durable job result,
   * so a reload mid-generation reclaims the Left/Right/Back cards too.
   */
  frames?: { view: string; label: string; key: string; imageUrl: string }[];
  /**
   * Client-generated id of the walkthrough render record. When set, the job's
   * outcome is persisted in the durable registry (video-jobs) so the client can
   * reclaim the result after a reload/crash instead of losing the paid clip.
   */
  jobId?: string;
}

interface StoreFrameBody {
  mode: "store-frame";
  projectId: string;
  /** a frame (data URI) the client extracted from the video, to persist + serve */
  image: string;
}

interface SlideshowBody {
  mode: "slideshow";
  projectId: string;
  /** ordered storage keys of the stills to play, each held `secondsEach` seconds */
  imageKeys: string[];
  secondsEach?: number;
}

interface ConsistencyBody {
  mode: "consistency";
  projectId: string;
  style: DesignStyle;
  /** the room's view photos (data URIs) to compare for one coherent design */
  views: { label: string; image: string }[];
}

type RenderBody =
  | GenerateBody
  | InpaintBody
  | PanoBody
  | VideoBody
  | StoreFrameBody
  | SlideshowBody
  | ConsistencyBody;

export async function POST(request: Request) {
  let body: RenderBody;
  try {
    body = (await request.json()) as RenderBody;
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  try {
    if (body.mode === "generate") return await handleGenerate(body);
    if (body.mode === "inpaint") return await handleInpaint(body);
    if (body.mode === "pano") return await handlePano(body);
    if (body.mode === "video") return await handleVideo(body);
    if (body.mode === "store-frame") return await handleStoreFrame(body);
    if (body.mode === "slideshow") return await handleSlideshow(body);
    if (body.mode === "consistency") return await handleConsistency(body);
    return Response.json({ error: "Unknown render mode" }, { status: 400 });
  } catch (e) {
    const message = e instanceof Error ? e.message : "Render failed";
    return Response.json({ error: message }, { status: 500 });
  }
}

async function handleGenerate(body: GenerateBody) {
  // A view of a DESIGNED room can only be reproduced from its own 3D screenshot
  // (or an existing render to edit). With NEITHER, every engine can only invent
  // a DIFFERENT room and label it as this one — fabrication, and exactly what
  // made each view of a room look like a completely different room: an ungrounded
  // text-to-image "retry" per view. Refuse instead of inventing.
  if (!body.image) {
    return Response.json(
      {
        error:
          "This view can't be re-rendered from here — it needs the room's 3D framing. " +
          "Open the room and use “Render front view”; for Left / Right / Back, open that front " +
          "render and use “Generate walkthrough video” (they are frames of one clip, so they " +
          "cannot be regenerated one at a time).",
      },
      { status: 400 },
    );
  }

  const hasFlux = fluxConfigured();
  // Nano Banana renders a view from its 3D screenshot; FLUX img2img is the
  // fallback when Gemini is off/busy. Both are GROUNDED in the screenshot above.
  const canNano = geminiImageConfigured() && !!body.image;
  if (!hasFlux && !canNano) {
    return Response.json(
      {
        error:
          "Image generation isn't configured. Set FAL_KEY (FLUX) or GEMINI_API_KEY (Nano Banana) to enable renders.",
      },
      { status: 503 },
    );
  }

  const basePrompt = buildRenderPrompt({
    view: body.view,
    style: body.style,
    propertyType: body.propertyType,
    plan: body.plan,
    items: body.items ?? [],
    notes: body.notes,
  });

  // (A) FOLLOW-UP view anchored to the hero IMAGE (user-chosen consistency mode).
  // Nano Banana takes the hero's exact materials / furniture / theme from IMAGE 2
  // (the hero render) while THIS view's own 3D screenshot (IMAGE 1) dictates the
  // camera — so the design is identical but the angle still changes.
  if (body.anchorKey && canNano) {
    let anchored: { bytes: Buffer; contentType: string } | null = null;
    try {
      const heroBuf = await getObject(body.anchorKey);
      const heroUri = `data:image/png;base64,${heroBuf.toString("base64")}`;
      anchored = await renderViewFromAnchor(
        heroUri,
        body.image!,
        body.view,
        body.style,
        body.notes,
        cameraDescription(body.view),
        // Ground the anchored view in the SAME strict room + furniture dimensions
        // as the hero, so it renders the space at the identical true scale — and,
        // for a wall view, the camera-oriented placement lock so the side still
        // puts every piece exactly where the plan says (not just the hero's look).
        buildIdentityBrief({ style: body.style, items: body.items ?? [], plan: body.plan, view: body.view }),
      );
    } catch {
      /* anchored stays null → handled just below */
    }
    if (anchored) {
      // Verify against the plan's furniture list + repair missing pieces BEFORE
      // storing — this still feeds the walkthrough orbit, so a dropped piece
      // here would get cemented into four Veo segments.
      const checked = await verifyAndRepairRender({
        bytes: anchored.bytes,
        contentType: anchored.contentType,
        screenshotDataUri: body.image!,
        items: body.items ?? [],
        style: body.style,
      });
      const key = await store(body.projectId, checked.bytes, checked.contentType);
      return Response.json({
        key,
        imageUrl: imageUrl(key),
        prompt: basePrompt,
        engine: "nano-banana-anchor",
        checklist: checked.checklist,
        extras: checked.extras,
        verified: checked.verified,
      });
    }
    // The anchored render (the identical-design side still) failed. When the
    // caller REQUIRES the anchor — the walkthrough sides, which MUST match the
    // edited front photo — do NOT fall through to an unanchored render: that
    // silently produces a side whose design differs, which then gets filmed
    // into the orbit as "the design changes as the camera turns". Surface a
    // retry so the walkthrough refilms cleanly instead of degrading.
    if (body.requireAnchor) {
      return Response.json(
        {
          error:
            "This side couldn't be matched to your edited front photo (the photoreal engine is busy or " +
            "rate-limited). Retry the walkthrough in a moment — the four sides must share one design, so " +
            "an unmatched side is rejected rather than filmed.",
        },
        { status: 502 },
      );
    }
    /* not required — fall through to the default Nano/FLUX path */
  }

  // (B) HERO via FLUX (user-chosen): image-to-image from the hero's 3D screenshot.
  // FLUX has a seed and hews to the screenshot's structure; the anchored Nano
  // views above then match its look. Falls through if FLUX returns nothing.
  if (body.heroFlux && hasFlux && body.image) {
    const prompt = await refinePromptWithGemini(basePrompt, body.style);
    const image = await generateImage(prompt, body.view, body.image, body.seed);
    if (image) {
      const key = await store(body.projectId, image.bytes, image.contentType);
      return Response.json({ key, imageUrl: imageUrl(key), prompt, engine: "flux-img2img-hero" });
    }
  }

  // PRIMARY for a room view: Nano Banana repaints the blocky 3D massing into a
  // photoreal, magazine-quality interior. Crucially, EVERY view renders from its
  // OWN 3D screenshot (the camera authority) so the angles genuinely differ.
  //
  // Cross-view consistency: the room's HERO is rendered first; the other views then
  // get the hero as a SOFT style reference (`styleRefKey`, loaded here as the styleRef
  // image) PLUS the hero's text look-spec. The screenshot keeps each view's own
  // camera/layout while the hero image+text lock the materials/furniture/design — so
  // the design matches across angles WITHOUT the camera collapsing. (A HARD anchor —
  // `renderViewFromAnchor` — made every angle copy the hero; a soft styleRef does
  // NOT, verified 2026-06-28 on real renders.)
  if (canNano) {
    try {
      const isFollowUp = !!body.lookSpec?.trim();
      const description = isFollowUp
        ? `${basePrompt}\nReproduce this EXACT look from the room's hero photo — identical wall/floor/ceiling colours, identical materials and finishes, and the same furniture design and colours (ONLY the camera angle differs from the hero): ${body.lookSpec!.trim()}`
        : basePrompt;
      // A hero key (the room's first render) becomes the SOFT style reference —
      // loaded server-side so the big hero image isn't shipped through the client.
      let styleRefUri = body.styleRef;
      if (body.styleRefKey) {
        try {
          const buf = await getObject(body.styleRefKey);
          styleRefUri = `data:image/png;base64,${buf.toString("base64")}`;
        } catch {
          /* hero not found — keep the user's styleRef (if any) */
        }
      }
      const rendered = await renderPhotorealFromScreenshot(
        body.image!,
        description,
        body.view,
        body.style,
        body.references,
        styleRefUri,
      );
      if (rendered) {
        // Verify the render against the plan's furniture list and repair any
        // missing piece in place (targeted edit, so verified items can't be
        // lost) BEFORE storing or describing it.
        const checked = await verifyAndRepairRender({
          bytes: rendered.bytes,
          contentType: rendered.contentType,
          screenshotDataUri: body.image!,
          items: body.items ?? [],
          style: body.style,
        });
        const key = await store(body.projectId, checked.bytes, checked.contentType);
        // Describe the HERO once so the room's other angles can match it by text.
        // Runs on the VERIFIED image — the look-spec must describe what's stored.
        let lookSpec: string | undefined;
        if (!isFollowUp) {
          const heroUri = `data:${checked.contentType};base64,${checked.bytes.toString("base64")}`;
          lookSpec = (await describeRoomLook(heroUri, body.style)) ?? undefined;
        }
        return Response.json({
          key,
          imageUrl: imageUrl(key),
          prompt: description,
          engine: isFollowUp ? "nano-banana-matched" : "nano-banana",
          checklist: checked.checklist,
          extras: checked.extras,
          verified: checked.verified,
          ...(lookSpec ? { lookSpec } : {}),
        });
      }
    } catch {
      /* fall through to FLUX */
    }
  }

  // Room views opt OUT of the blocky FLUX img2img fallback: if Nano Banana was
  // available but didn't return an image (busy / rate-limited), surface a clear
  // retry instead of a rough, blocky FLUX render that looks like an unfinished 3D
  // model. Only applies when Nano was actually an option — if Gemini is unconfigured
  // (canNano false) we still want FLUX as the only engine.
  if (body.noFluxFallback && canNano) {
    return Response.json(
      {
        error:
          "The photoreal engine (Nano Banana) is busy or rate-limited right now. Please retry this render in a moment — its free-tier quota may be exhausted; enabling Gemini billing removes this.",
      },
      { status: 502 },
    );
  }

  // Fallback: FLUX image-to-image (Gemini off, or Nano returned nothing). A fixed
  // per-room seed keeps colours/materials consistent across the views. Still
  // GROUNDED in the 3D screenshot, so it renders THIS room.
  //
  // There is deliberately NO text-to-image last resort: without the screenshot an
  // engine cannot know what this room looks like, so it would return a different
  // room every time (see the guard at the top of this handler).
  if (hasFlux) {
    const prompt = await refinePromptWithGemini(basePrompt, body.style);
    const image = await generateImage(prompt, body.view, body.image, body.seed);
    if (image) {
      const key = await store(body.projectId, image.bytes, image.contentType);
      return Response.json({ key, imageUrl: imageUrl(key), prompt, engine: "flux-img2img" });
    }
  }
  return Response.json(
    { error: "Render engine returned no image. Check your fal.ai / Gemini keys and credits." },
    { status: 502 },
  );
}

async function handleInpaint(body: InpaintBody) {
  if (!body.baseKey || !body.mask) {
    return Response.json({ error: "baseKey and mask are required" }, { status: 400 });
  }
  if (!geminiImageConfigured() && !fluxConfigured()) {
    return Response.json(
      {
        error:
          "Selective edit isn't configured. Set GEMINI_API_KEY (Nano Banana) or FAL_KEY (FLUX).",
      },
      { status: 503 },
    );
  }

  // Read the base render back from storage as a data URI.
  let baseDataUri: string;
  try {
    const base = await getObject(body.baseKey);
    baseDataUri = `data:image/png;base64,${base.toString("base64")}`;
  } catch {
    return Response.json({ error: "Base render not found in storage" }, { status: 404 });
  }

  // Primary: Nano Banana (Gemini image editing) — best at adding/replacing
  // objects from a plain instruction like "add an AC there". Falls back to FLUX
  // masked inpainting if Gemini is unconfigured or returns nothing.
  let image = geminiImageConfigured()
    ? await editImageWithGemini(baseDataUri, body.mask, body.instruction, body.style, body.reference)
    : null;
  let engine = "nano-banana";
  let prompt = body.instruction.trim();

  // Lasso edits opt OUT of the constrained FLUX-Fill fallback: when Nano Banana was
  // available but busy/returned nothing, surface a clear retry instead of a FLUX-Fill
  // edit confined to the strict lasso outline (Nano expands to the whole intended
  // object/area; FLUX-Fill does not, so it reads as "the edit didn't work").
  if (!image && body.noFluxFallback && geminiImageConfigured()) {
    return Response.json(
      {
        error:
          "The smart edit engine (Nano Banana) is busy or rate-limited right now. Please retry in a moment — its free-tier quota may be exhausted; enabling Gemini billing removes this.",
      },
      { status: 502 },
    );
  }

  if (!image && fluxConfigured()) {
    // Give FLUX-Fill a polished, Gemini-refined prompt (best-effort).
    prompt = await refinePromptWithGemini(buildInpaintPrompt(body.instruction, body.style), body.style);
    image = await inpaintImage(prompt, baseDataUri, body.mask);
    engine = "flux";
  }

  if (!image) {
    return Response.json(
      {
        error:
          "The selective edit didn't return an image. Nano Banana may be rate-limited — try again, or set FAL_KEY for a FLUX fallback.",
      },
      { status: 502 },
    );
  }

  const key = await store(body.projectId, image.bytes, image.contentType);
  return Response.json({ key, imageUrl: imageUrl(key), prompt, engine });
}

async function handlePano(body: PanoBody) {
  const keys = (body.imageKeys ?? []).filter(Boolean);
  if (!keys.length) return Response.json({ error: "imageKeys are required" }, { status: 400 });

  // Load the rendered views back from storage as data URIs.
  const views: string[] = [];
  for (const k of keys) {
    try {
      const buf = await getObject(k);
      views.push(`data:image/png;base64,${buf.toString("base64")}`);
    } catch {
      /* skip a missing view */
    }
  }

  // Primary: merge the views into one consistent 360° panorama (Nano Banana).
  let image = views.length ? await makePanoramaFromViews(views, body.style) : null;
  let prompt = "360° panorama merged from the room views";

  // Fallback: a text-to-image equirectangular panorama in the chosen style.
  if (!image && fluxConfigured()) {
    prompt = buildRenderPrompt({
      view: "pano",
      style: body.style,
      propertyType: body.propertyType,
      items: [],
      notes: body.notes,
    });
    image = await generateImage(prompt, "pano");
  }

  if (!image) {
    return Response.json(
      { error: "Couldn't build the 360° panorama. Render the room's views first, then retry." },
      { status: 502 },
    );
  }

  const key = await store(body.projectId, image.bytes, image.contentType);
  return Response.json({ key, imageUrl: imageUrl(key), prompt });
}

/**
 * Orbit-video pass: turn the room's front render into a Veo clip that pans around
 * the room. The client then extracts the Front/Left/Right/Back stills from it. The
 * clip is ONE coherent generation, so every extracted frame is the SAME room —
 * which is how the multi-angle views stay consistent.
 */
async function handleVideo(body: VideoBody) {
  if (!veoConfigured()) {
    return Response.json(
      { error: "Video generation isn't configured. Set GEMINI_API_KEY (Veo) to enable it." },
      { status: 503 },
    );
  }
  if (!body.image) {
    return Response.json({ error: "image (the front render) is required" }, { status: 400 });
  }
  if (body.jobId) createVideoJob(body.jobId, body.projectId);
  try {
    const canOrbit =
      body.sides?.front && body.sides.right && body.sides.back && body.sides.left &&
      body.segmentPrompts?.length === 4;
    return canOrbit ? await runOrbitVideo(body) : await runVideo(body);
  } catch (e) {
    // Without this, an unexpected throw would leave the job "processing"
    // forever — the reconcile pass would poll it to no end instead of
    // surfacing a failed record the user can retry.
    if (body.jobId) failVideoJob(body.jobId, (e as Error).message || "Video failed");
    throw e;
  }
}

/**
 * The GROUNDED 360° walkthrough: four Veo quarter-turn clips — each pinned to a
 * real still at BOTH ends (first frame = this side's photo, last frame = the next
 * side's, clockwise F→R→B→L→F) — concatenated into one seamless orbit.
 *
 * Pinning both endpoints is the structural fix for the walkthrough hallucinations
 * (drifting motion that never reached the back wall, furniture/plants appearing
 * and disappearing): Veo no longer invents the unseen 270° from one photo — it
 * only fills a 90° turn between two grounded photos of the SAME room, and every
 * wall gets exactly one segment = exactly equal screen time.
 */
async function runOrbitVideo(body: VideoBody) {
  const sides = body.sides!;
  const stills = [sides.front, sides.right, sides.back, sides.left];
  const prompts = body.segmentPrompts!;
  const stage = (s: string) => body.jobId && stageVideoJob(body.jobId, s);

  if (!ffmpegAvailable()) {
    const error = "Video assembly isn't available (ffmpeg missing) — can't stitch the orbit segments.";
    if (body.jobId) failVideoJob(body.jobId, error);
    return Response.json({ error }, { status: 503 });
  }

  // Film the four quarter-turns, two at a time (Veo preview quotas are tight —
  // four concurrent long-running ops trip the per-project limit). Each segment
  // interpolates still[i] → still[(i+1) % 4].
  const NEGATIVE = "people, humans, hands, text, captions, watermark, warped or melting furniture, extra furniture, flicker";
  const segs: (Buffer | null)[] = [null, null, null, null];
  // Segments that filmed but couldn't be pinned to their end frame (grounded at
  // the start only) → the seam into the next side drifts. Tracked so the user is
  // WARNED instead of silently getting a walkthrough where a side morphs.
  const drifted: number[] = [];
  let filmed = 0;
  const film = async (i: number) => {
    const clip = await generateVideoFromImage(stills[i], prompts[i], {
      lastFrameDataUri: stills[(i + 1) % 4],
      durationSeconds: 4,
      negativePrompt: NEGATIVE,
    });
    segs[i] = clip?.bytes ?? null;
    if (clip && !clip.lastFrameHonored) drifted.push(i);
    filmed++;
    stage(`Filming the orbit — ${filmed}/4 quarter-turns done…`);
  };
  stage("Filming the orbit — 4 quarter-turns (this takes a few minutes)…");
  for (const pair of [[0, 1], [2, 3]]) {
    await Promise.all(pair.map(film));
  }

  const missing = segs
    .map((s, i) => (s ? null : ["front→right", "right→back", "back→left", "left→front"][i]))
    .filter(Boolean);
  if (missing.length) {
    const error =
      `Veo didn't return ${missing.length}/4 orbit segments (${missing.join(", ")}). ` +
      "Common causes: Gemini API credits depleted (top up at ai.studio) or a rate limit — retry in a minute.";
    if (body.jobId) failVideoJob(body.jobId, error);
    return Response.json({ error }, { status: 502 });
  }

  stage("Stitching the four quarter-turns into one 360° clip…");
  const mp4 = await concatVideos(segs as Buffer[]);
  const rawKey = await store(body.projectId, mp4, "video/mp4");

  // Fail LOUD (but don't discard the paid clip) when Veo couldn't pin a segment
  // to its end frame — that turn is grounded at its start only, so the room can
  // drift before the next side. The user sees exactly which turns and can retry.
  const SEG_LABELS = ["front→right", "right→back", "back→left", "left→front"];
  const warning = drifted.length
    ? `${drifted.length}/4 turns (${drifted.map((i) => SEG_LABELS[i]).join(", ")}) couldn't be pinned to ` +
      `their end frame, so placements may drift there. Veo's frames-to-video interpolation was unavailable — ` +
      `retry the walkthrough for a cleaner orbit.`
    : undefined;

  // The gallery stills were already rendered + stored by the client (they are
  // the segment endpoints) — echo them into the durable result so a reload
  // mid-generation reclaims the Left/Right/Back cards along with the clip.
  const payload = {
    key: rawKey,
    videoUrl: imageUrl(rawKey),
    frames: body.frames ?? [],
    ...(warning ? { warning } : {}),
  };
  if (body.jobId) completeVideoJob(body.jobId, payload);
  return Response.json(payload);
}

async function runVideo(body: VideoBody) {
  const video = await generateVideoFromImage(body.image, body.prompt);
  if (!video) {
    const error =
      "The walkthrough video didn't come back from Veo (Gemini video). Common causes: Gemini API credits depleted (top up at ai.studio), a rate limit, or a transient error — check the server logs and retry.";
    if (body.jobId) failVideoJob(body.jobId, error);
    return Response.json({ error }, { status: 502 });
  }

  // The RAW Veo clip IS the walkthrough: ONE continuous tripod pan (no cuts —
  // hard cuts let Veo re-imagine a fresh room per segment, which is exactly the
  // "different room per view" hallucination). Return the clip UNMODIFIED so it
  // matches the Veo output exactly; re-encoding it into a slideshow only degraded it.
  const rawKey = await store(body.projectId, video.bytes, video.contentType);

  // Best-effort: pull the Right/Back/Left stills out of the SAME clip for the
  // gallery cards. The pan rotates clockwise at constant speed (0s front →
  // 2s right → 4s back → 6s left → 8s front), so sample the quarter turns.
  // Keep in sync with FRAME_SAMPLES in src/lib/room-video.ts.
  const SAMPLES: { view: "left" | "right" | "back"; label: string; at: number }[] = [
    { view: "right", label: "Right", at: 0.25 },
    { view: "back", label: "Back", at: 0.5 },
    { view: "left", label: "Left", at: 0.75 },
  ];
  const frames: { view: string; label: string; key: string; imageUrl: string }[] = [];
  if (ffmpegAvailable()) {
    try {
      const bufs = await extractFramesFromVideo(video.bytes, SAMPLES.map((s) => s.at));
      for (let i = 0; i < bufs.length; i++) {
        const fkey = await store(body.projectId, bufs[i], "image/jpeg");
        frames.push({ view: SAMPLES[i].view, label: SAMPLES[i].label, key: fkey, imageUrl: imageUrl(fkey) });
      }
    } catch (e) {
      console.warn("[video] ffmpeg frame extraction failed:", (e as Error).message);
    }
  }

  // Persist the outcome BEFORE responding: if the awaiting tab died during the
  // ~100s generation, the reconcile pass reclaims the clip from this record —
  // the paid Veo output must never depend on one browser tab staying alive.
  const payload = { key: rawKey, videoUrl: imageUrl(rawKey), frames };
  if (body.jobId) completeVideoJob(body.jobId, payload);
  return Response.json(payload);
}

/**
 * Stitch stored stills (Front + Left/Right/Back) into a HARD-CUT slideshow video,
 * each frame held `secondsEach` seconds — the "walkthrough" that waits on each angle.
 */
async function handleSlideshow(body: SlideshowBody) {
  const keys = (body.imageKeys ?? []).filter(Boolean);
  if (keys.length < 2) {
    return Response.json({ error: "Need at least two frames for a walkthrough" }, { status: 400 });
  }
  if (!ffmpegAvailable()) {
    return Response.json({ error: "Video assembly isn't available (ffmpeg missing)." }, { status: 503 });
  }
  const bufs: Buffer[] = [];
  for (const k of keys) {
    try {
      bufs.push(await getObject(k));
    } catch {
      /* skip a missing frame */
    }
  }
  if (bufs.length < 2) {
    return Response.json({ error: "Couldn't load the frames to stitch" }, { status: 502 });
  }
  try {
    const mp4 = await assembleSlideshow(bufs, body.secondsEach ?? 2);
    const key = await store(body.projectId, mp4, "video/mp4");
    return Response.json({ key, videoUrl: imageUrl(key) });
  } catch (e) {
    return Response.json({ error: (e as Error).message || "Slideshow assembly failed" }, { status: 502 });
  }
}

/**
 * Cross-view consistency check for the walkthrough: do the room's four view
 * photos show ONE coherent design? Run before filming so a drifting still is
 * caught (and can be retried) instead of cemented into four Veo segments.
 */
async function handleConsistency(body: ConsistencyBody) {
  const views = (body.views ?? []).filter((v) => v?.image);
  if (views.length < 2) return Response.json({ consistent: true, issues: [] });
  const res = await checkViewConsistency(
    views.map((v) => ({ label: v.label, dataUri: v.image })),
    body.style,
  );
  return Response.json(res);
}

/** Persist a frame the client extracted from the orbit video, and serve it back. */
async function handleStoreFrame(body: StoreFrameBody) {
  const m = body.image?.match(/^data:([^;]+);base64,([\s\S]*)$/);
  if (!m) {
    return Response.json({ error: "image must be a data URI" }, { status: 400 });
  }
  const bytes = Buffer.from(m[2], "base64");
  const key = await store(body.projectId, bytes, m[1]);
  return Response.json({ key, imageUrl: imageUrl(key) });
}

async function store(projectId: string, bytes: Buffer, contentType: string): Promise<string> {
  const ext = contentType.includes("mp4")
    ? "mp4"
    : contentType.includes("jpeg")
      ? "jpg"
      : "png";
  const safeId = projectId.replace(/[^a-zA-Z0-9_-]/g, "");
  const key = `renders/${safeId}/${randomUUID()}.${ext}`;
  const ref = await putObject(key, bytes, contentType);
  return ref.key;
}

const imageUrl = (key: string) => `/api/render?key=${encodeURIComponent(key)}`;

/**
 * GET ?key — stream a stored render image back to the browser.
 * GET ?videoJob — look up a walkthrough job in the durable registry, so the
 * client can reclaim a clip whose response never reached it (reload mid-run).
 */
export async function GET(request: Request) {
  const params = new URL(request.url).searchParams;

  const videoJob = params.get("videoJob");
  if (videoJob) {
    const job = await getVideoJob(videoJob);
    if (!job) return Response.json({ error: "Job not found" }, { status: 404 });
    return Response.json({
      status: job.status,
      stage: job.stage ?? null,
      result: job.result ?? null,
      error: job.error ?? null,
      updatedAt: job.updatedAt,
    });
  }

  const key = params.get("key");
  if (!key) return Response.json({ error: "key required" }, { status: 400 });
  if (!key.startsWith("renders/")) {
    return Response.json({ error: "Invalid key" }, { status: 400 });
  }

  try {
    const bytes = await getObject(key);
    const contentType = key.endsWith(".mp4")
      ? "video/mp4"
      : key.endsWith(".jpg")
        ? "image/jpeg"
        : "image/png";
    return new Response(new Uint8Array(bytes), {
      headers: {
        "Content-Type": contentType,
        "Cache-Control": "public, max-age=31536000, immutable",
      },
    });
  } catch {
    return Response.json({ error: "Render not found" }, { status: 404 });
  }
}
